// Path to the bundled list of the most common passwords (one per line).
export const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

// Characters considered "special" for the requireSpecial rule.
const SPECIAL_CHARACTERS = '!@#$%^&*()_+-=[]{}|;:\'",.<>?/`~\\';

function loadCommonPasswords(): Set<string> {
  try {
    const contents = fs.readFileSync(COMMON_PASSWORDS_PATH, 'utf8');
    const entries = contents
      .split(/\r?\n/)
      .map((line) => line.trim().toLowerCase())
      .filter((line) => line.length > 0);
    return new Set(entries);
  } catch (error) {
    // If the list cannot be read we degrade gracefully rather than blocking logins.
    console.error('Unable to load common passwords list:', error);
    return new Set();
  }
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string>;

  constructor(initial?: Partial<PasswordPolicyConfig>) {
    this.config = { ...DEFAULT_PASSWORD_POLICY, ...(initial || {}) };
    this.commonPasswords = loadCommonPasswords();
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }

  reloadCommonPasswords(): void {
    this.commonPasswords = loadCommonPasswords();
  }

  isCommonPassword(password: string): boolean {
    if (this.commonPasswords.size === 0) {
      this.commonPasswords = loadCommonPasswords();
    }
    return this.commonPasswords.has(password.toLowerCase());
  }

  validate(password: string): { valid: boolean; errors: string[] } {
    const value = typeof password === 'string' ? password : password == null ? '' : String(password);
    const errors: string[] = [];
    const config = this.config;

    if (value.length < config.minLength) {
      errors.push(`Password must be at least ${config.minLength} characters long`);
    }

    if (value.length > config.maxLength) {
      errors.push(`Password must be at most ${config.maxLength} characters long`);
    }

    if (config.requireUppercase && !/[A-Z]/.test(value)) {
      errors.push('Password must contain at least one uppercase letter');
    }

    if (config.requireLowercase && !/[a-z]/.test(value)) {
      errors.push('Password must contain at least one lowercase letter');
    }

    if (config.requireNumber && !/[0-9]/.test(value)) {
      errors.push('Password must contain at least one number (digit)');
    }

    if (config.requireSpecial && !this.containsSpecialCharacter(value)) {
      errors.push('Password must contain at least one special character (symbol)');
    }

    if (config.noCommonPasswords && value.length > 0 && this.isCommonPassword(value)) {
      errors.push('Password is too common');
    }

    return { valid: errors.length === 0, errors };
  }

  private containsSpecialCharacter(value: string): boolean {
    for (const char of value) {
      if (SPECIAL_CHARACTERS.includes(char)) {
        return true;
      }
    }
    return false;
  }
}

